package com.onlymymoney.adapter.out.persistence;

import jakarta.persistence.*;

import java.math.BigDecimal;

/**
 * JPA entity mapped to the {@code categories} table.
 * <p>
 * It is the persistence representation of a category, which belongs to an account and holds
 * its own available balance.
 */
@Entity
@Table(name = "categories")
public class CategoryJpa {
    /** Primary key, generated by the database (identity column). */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    Long id;
    /** Identifier of the account this category belongs to. */
    @Column(name = "account_id")
    Long accountId;
    /** Human-readable description of the category. */
    String description;
    /** Balance currently available in the category, stored with precision 19 and scale 2. */
    @Column(name = "available_balance", precision = 19, scale = 2)
    BigDecimal availableBalance;
    /** Flag indicating whether this is the account's "general expenses" category. */
    @Column(name = "general_expenses")
    boolean generalExpenses;

    /**
     * Default constructor required by JPA.
     */
    public CategoryJpa() {
    }

    /**
     * Creates an entity with all its fields.
     *
     * @param id the identifier ({@code null} for a new category)
     * @param a  the account identifier
     * @param d  the description
     * @param b  the available balance
     * @param g  whether this is the general expenses category
     */
    public CategoryJpa(Long id, Long a, String d, BigDecimal b, boolean g) {
        this.id = id;
        accountId = a;
        description = d;
        availableBalance = b;
        generalExpenses = g;
    }

    /** @return the category identifier */
    public Long getId() {
        return id;
    }

    /** @return the identifier of the account the category belongs to */
    public Long getAccountId() {
        return accountId;
    }

    /** @return the category description */
    public String getDescription() {
        return description;
    }

    /** @return the balance available in the category */
    public BigDecimal getAvailableBalance() {
        return availableBalance;
    }

    /** @return {@code true} if this is the general expenses category */
    public boolean isGeneralExpenses() {
        return generalExpenses;
    }
}